use fixture::LruCache;

#[test]
fn evicts_least_recently_used() {
    let mut cache = LruCache::new(2);
    assert_eq!(cache.put("a", 1), None);
    assert_eq!(cache.put("b", 2), None);
    assert_eq!(cache.get(&"a"), Some(&1));
    assert_eq!(cache.put("c", 3), None);
    assert_eq!(cache.get(&"b"), None);
    assert_eq!(cache.keys(), ["c", "a"]);
    assert_eq!(cache.len(), 2);
    assert_eq!(cache.capacity(), 2);
}

#[test]
fn put_existing_key_replaces_without_eviction() {
    let mut cache = LruCache::new(2);
    cache.put(1, "one");
    cache.put(2, "two");
    assert_eq!(cache.put(1, "uno"), Some("one"));
    assert_eq!(cache.len(), 2);
    assert_eq!(cache.keys(), [1, 2]);
    cache.put(3, "three");
    assert_eq!(cache.peek(&2), None);
    assert_eq!(cache.peek(&1), Some(&"uno"));
    assert_eq!(cache.keys(), [3, 1]);
}

#[test]
fn peek_and_misses_do_not_touch_recency() {
    let mut cache = LruCache::new(2);
    cache.put('x', 10);
    cache.put('y', 20);
    assert_eq!(cache.peek(&'x'), Some(&10));
    assert_eq!(cache.get(&'z'), None);
    assert_eq!(cache.keys(), ['y', 'x']);
    cache.put('z', 30);
    assert_eq!(cache.keys(), ['z', 'y']);
}

#[test]
fn remove() {
    let mut cache = LruCache::new(3);
    cache.put("a", String::from("A"));
    cache.put("b", String::from("B"));
    assert_eq!(cache.remove(&"a"), Some(String::from("A")));
    assert_eq!(cache.remove(&"a"), None);
    assert_eq!(cache.len(), 1);
    cache.put("c", String::from("C"));
    cache.put("d", String::from("D"));
    assert_eq!(cache.len(), 3);
    assert_eq!(cache.keys(), ["d", "c", "b"]);
}

#[test]
fn zero_capacity_and_single_slot() {
    let mut empty = LruCache::new(0);
    assert_eq!(empty.put(1, 1), None);
    assert_eq!(empty.put(1, 2), None);
    assert!(empty.is_empty());
    assert_eq!(empty.get(&1), None);
    assert!(empty.keys().is_empty());

    let mut one = LruCache::new(1);
    one.put(1, 'a');
    one.put(2, 'b');
    assert_eq!(one.get(&1), None);
    assert_eq!(one.get(&2), Some(&'b'));
    assert_eq!(one.put(2, 'c'), Some('b'));
    assert_eq!(one.len(), 1);
}

#[test]
fn values_need_no_clone() {
    struct Opaque(u32);
    let mut cache = LruCache::new(1);
    cache.put("k", Opaque(7));
    assert_eq!(cache.get(&"k").map(|value| value.0), Some(7));
    assert_eq!(cache.remove(&"k").map(|value| value.0), Some(7));
}

#[test]
fn matches_reference_model() {
    // Deterministic pseudo-random operations checked against a simple list model.
    let mut state: u64 = 0x2545_f491_4f6c_dd1d;
    let mut next = move |bound: u64| {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state % bound
    };
    for capacity in [1usize, 2, 3, 5, 8] {
        let mut cache = LruCache::new(capacity);
        let mut model: Vec<(u64, u64)> = Vec::new(); // most recent first
        for step in 0..4000u64 {
            let key = next(12);
            match next(5) {
                0 | 1 => {
                    let expected = model.iter().position(|(k, _)| *k == key).map(|i| {
                        let entry = model.remove(i);
                        model.insert(0, entry);
                        entry.1
                    });
                    assert_eq!(cache.get(&key).copied(), expected, "get {key} at {step}");
                }
                2 | 3 => {
                    let old = model.iter().position(|(k, _)| *k == key).map(|i| model.remove(i).1);
                    if old.is_none() && model.len() == capacity {
                        model.pop();
                    }
                    model.insert(0, (key, step));
                    assert_eq!(cache.put(key, step), old, "put {key} at {step}");
                }
                _ => {
                    let old = model.iter().position(|(k, _)| *k == key).map(|i| model.remove(i).1);
                    assert_eq!(cache.remove(&key), old, "remove {key} at {step}");
                }
            }
            assert_eq!(cache.len(), model.len());
            let keys: Vec<u64> = model.iter().map(|(k, _)| *k).collect();
            assert_eq!(cache.keys(), keys, "order at {step}");
        }
    }
}
